package web

import (
	"bytes"
	"fmt"
	"net/http"
	"runtime"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/brnl/k8s-app-standby-toggle/internal/controller"
)

// Metric names. They are a stable interface: the homelab uses
// k8s_app_standby_toggle_group_should_be_awake and
// k8s_app_standby_toggle_application_should_be_awake to silence probe
// alerts for sleeping apps.
const (
	metricPrefix = "k8s_app_standby_toggle_"
)

// metrics writes the Prometheus text exposition format (0.0.4), generated by
// hand to keep the binary small.
func (s *server) metrics(w http.ResponseWriter, _ *http.Request) {
	var m metricsWriter
	st := s.Controller.Status()

	m.family("build_info", "gauge", "Build information.")
	m.sample("build_info", 1, "version", s.Version, "goversion", runtime.Version())

	m.family("reconciles_total", "counter", "Reconcile passes.")
	m.sample("reconciles_total", float64(st.Reconciles))
	m.family("reconcile_errors_total", "counter", "Errors during reconcile passes (state, Application list or resource actions).")
	m.sample("reconcile_errors_total", float64(st.ErrorsTotal))
	m.family("last_reconcile_timestamp_seconds", "gauge", "Time the last reconcile pass ended (0 before the first).")
	m.sample("last_reconcile_timestamp_seconds", unix(st.LastLoop))
	m.family("kubernetes_api_reachable", "gauge", "Whether the last reconcile pass reached the Kubernetes API.")
	m.sample("kubernetes_api_reachable", boolValue(st.APIOK))

	// Group series appear once the stored state has been read, so that a
	// restart never reports a wrong "should be awake".
	var views []controller.GroupView
	if s.Controller.StateLoaded() {
		views = s.Controller.Views()
	}
	m.family("group_should_be_awake", "gauge", "Whether the group's effective state is awake (1) or asleep (0).")
	for _, v := range views {
		m.sample("group_should_be_awake", boolValue(v.Desired == "awake"), "group", v.Name)
	}
	m.family("group_ready", "gauge", "Whether the group should be awake and all its resources are ready.")
	for _, v := range views {
		m.sample("group_ready", boolValue(v.Ready), "group", v.Name)
	}
	m.family("group_held", "gauge", "Whether the group has an unexpired hold.")
	for _, v := range views {
		m.sample("group_held", boolValue(v.Hold != nil), "group", v.Name)
	}
	m.family("group_conflict", "gauge", "Whether the service stopped acting on the group because something else undoes its work.")
	for _, v := range views {
		m.sample("group_conflict", boolValue(v.Conflict != nil), "group", v.Name)
	}
	m.family("group_leases", "gauge", "Number of unexpired leases on the group.")
	for _, v := range views {
		m.sample("group_leases", float64(len(v.Leases)), "group", v.Name)
	}
	m.family("group_phase", "gauge", "The group's observed phase (1 for the current phase).")
	for _, v := range views {
		for _, p := range controller.Phases {
			m.sample("group_phase", boolValue(v.Phase == p), "group", v.Name, "phase", p)
		}
	}
	m.family("application_should_be_awake", "gauge", "Whether the Application's group should be awake (1) or asleep (0).")
	for _, v := range views {
		for _, app := range v.Apps {
			m.sample("application_should_be_awake", boolValue(v.Desired == "awake"), "group", v.Name, "application", app)
		}
	}
	m.family("application_missing", "gauge", "Whether a configured Application does not exist in the cluster.")
	for _, v := range views {
		missing := map[string]bool{}
		for _, a := range v.Missing {
			missing[a] = true
		}
		for _, app := range v.Apps {
			m.sample("application_missing", boolValue(missing[app]), "group", v.Name, "application", app)
		}
	}

	w.Header().Set("Content-Type", "text/plain; version=0.0.4; charset=utf-8")
	_, _ = w.Write(m.buf.Bytes())
}

type metricsWriter struct{ buf bytes.Buffer }

func (m *metricsWriter) family(name, typ, help string) {
	fmt.Fprintf(&m.buf, "# HELP %s%s %s\n# TYPE %s%s %s\n", metricPrefix, name, help, metricPrefix, name, typ)
}

// sample writes one sample; labels are name/value pairs.
func (m *metricsWriter) sample(name string, value float64, labels ...string) {
	m.buf.WriteString(metricPrefix + name)
	if len(labels) > 0 {
		pairs := make([]string, 0, len(labels)/2)
		for i := 0; i+1 < len(labels); i += 2 {
			pairs = append(pairs, labels[i]+`="`+labelEscaper.Replace(labels[i+1])+`"`)
		}
		sort.Strings(pairs)
		m.buf.WriteString("{" + strings.Join(pairs, ",") + "}")
	}
	m.buf.WriteString(" " + strconv.FormatFloat(value, 'f', -1, 64) + "\n")
}

var labelEscaper = strings.NewReplacer(`\`, `\\`, `"`, `\"`, "\n", `\n`)

// unix returns t in seconds since the epoch, or 0 for the zero time.
func unix(t time.Time) float64 {
	if t.IsZero() {
		return 0
	}
	return float64(t.UnixMilli()) / 1000
}

func boolValue(b bool) float64 {
	if b {
		return 1
	}
	return 0
}
